def feature(s):
    if not s:
        return 0.0
    props = s.get('element_properties') or {}
    spheres = 0.0
    occupied = 0.0
    for site in s.get('sites') or []:
        o = site.get('occupancy')
        o = max(0.0, o if o is not None else 1.0)
        occupied += o
        r = (props.get(site.get('element')) or {}).get('covalent_radius_A')
        if r is not None and r > 0:
            spheres += o * r ** 3
    volume = (s.get('lattice') or {}).get('volume_A3')
    if volume is None or volume <= 0:
        v = s.get('volume_per_atom_A3')
        volume = v * occupied if v is not None and v > 0 else 0.0
    return 4.0 * pi * spheres / (3.0 * volume) if volume > 0 else 0.0

def feature(s):
    if not s:
        return 0.0
    sites = s.get('sites') or []
    n = len(sites)
    props = s.get('element_properties') or {}
    radii = []
    chi = []
    hardness = []
    occ = []
    for site in sites:
        p = props.get(site.get('element')) or {}
        radii.append(p.get('covalent_radius_A'))
        ion = p.get('first_ionization_energy_eV')
        affinity = p.get('electron_affinity_eV')
        if ion is not None and affinity is not None and ion > affinity:
            chi.append(0.5 * (ion + affinity))
            hardness.append(0.5 * (ion - affinity))
        else:
            chi.append(None)
            hardness.append(None)
        o = site.get('occupancy')
        occ.append(max(0.0, o if o is not None else 1.0))
    value = 0.0
    for edge in s.get('neighbors') or []:
        i = edge.get('i', -1)
        j = edge.get('j', -1)
        d = edge.get('distance_A')
        if 0 <= i < n and 0 <= j < n and d is not None and d > 0:
            a = radii[i]
            b = radii[j]
            if a is not None and b is not None and a > 0 and b > 0 and d <= 1.3 * (a + b):
                if chi[i] is not None and chi[j] is not None:
                    denominator = 2.0 * (hardness[i] + hardness[j])
                    if denominator > 0:
                        value += occ[i] * occ[j] * (chi[i] - chi[j]) ** 2 / denominator
    total = sum(occ)
    return 0.5 * value / total if total > 0 else 0.0
